"""Castle labels compare width-insensitively.

Measured live (local g1190, chapter 9 = 9わ 53ねん, 2026-11-17 17:2x JST):
the native castle-status panel reads ``イデ!`` (ASCII '!') while the source
catalog spells the castle ``イデ！`` (U+FF01).  ``map_registration._label``
compared the raw strings, answered "name unknown" three times per general
and month, and the general stayed out of the sortie plan.  The raw screen
text from that observation is reproduced below.
"""
from docich.hanjuku_speedrun.hanjuku.flows import map_registration
from docich.hanjuku_speedrun.hanjuku.os_layer.font import TextLine
from docich.hanjuku_speedrun.hanjuku_screen import Screen

# screen.text as recorded in post_month_castle_location_unverified.
MEASURED_TEXT = ('しゅつげきイデ!じょうステータスしゅうにゅう30G'
                 'レベル1しょうぐん2めいどうしブラウニー')


def _line(text, y, x=16):
    return TextLine(y, tuple((x + 8 * i, ch) for i, ch in enumerate(text)))


def _castle_menu(text, rows):
    return Screen(lines=[_line(row, 31 + 16 * i) for i, row in enumerate(rows)],
                  hand=(16, 8), text=text, kind='castle_menu')


def test_ascii_exclamation_reads_the_full_width_catalog_name():
    screen = _castle_menu(MEASURED_TEXT, ['しゅつげきイデ!じょう',
                                         'ステータスしゅうにゅう30G'])
    assert map_registration._label(screen, 9) == 'イデ！'


def test_full_width_glyph_still_reads_the_same_name():
    screen = _castle_menu(MEASURED_TEXT.replace('イデ!', 'イデ！'),
                          ['しゅつげきイデ！じょう', 'ステータスしゅうにゅう30G'])
    assert map_registration._label(screen, 9) == 'イデ！'


def test_an_unknown_castle_label_is_still_rejected():
    text = MEASURED_TEXT.replace('イデ!', 'ゾゾ!')
    screen = _castle_menu(text, ['しゅつげきゾゾ!じょう', 'ステータスしゅうにゅう30G'])
    assert map_registration._label(screen, 9) is None


def test_fold_only_equalises_width_and_spaces():
    assert map_registration._fold('イデ！') == map_registration._fold('イデ!')
    assert map_registration._fold('イ デ！') == 'イデ!'
    assert map_registration._fold('ハヤク') == 'ハヤク'
